"use client";
/* Bees, from the Piixpal shadcn registry. Options: https://piixpal.vercel.app/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Bees(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("bees"); }, []);
  return React.createElement("piix-pal", { "pal": "bees", ...piixAttrs(props) });
}

export default Bees;
